REVOKE EXECUTE ON FUNCTION public.finish_support_turn(uuid,uuid,jsonb) FROM authenticated;
CREATE FUNCTION public.complete_support_turn(_conversation_id uuid,_user_id uuid,_token uuid,_parts jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE mid uuid; BEGIN UPDATE public.support_conversations SET processing_token=NULL,processing_until=NULL WHERE id=_conversation_id AND user_id=_user_id AND processing_token=_token; IF NOT FOUND THEN RAISE EXCEPTION 'Conversation unavailable'; END IF; IF _parts IS NOT NULL THEN IF jsonb_typeof(_parts)<>'array' OR length(_parts::text)>20000 THEN RAISE EXCEPTION 'Invalid response'; END IF; INSERT INTO public.support_messages(conversation_id,role,parts) VALUES(_conversation_id,'assistant',_parts) RETURNING id INTO mid; END IF; RETURN mid; END; $$;
REVOKE ALL ON FUNCTION public.complete_support_turn(uuid,uuid,uuid,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.complete_support_turn(uuid,uuid,uuid,jsonb) TO service_role;